<?php $days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado']; ?>
<div class="disp-grid"><section class="cartao configuracao"><div class="cartao-cabecalho"><div><h2>Horários semanais</h2><p>Intervalos em horário de São Paulo. Consultas agendadas são preservadas.</p></div><a href="#novo-intervalo" class="botao botao-principal"><?= icon('plus') ?> Adicionar horário</a></div><div class="semana-lista"><?php foreach($d['disponibilidade']['weekly'] as $w): ?><details><summary><?= $days[(int)$w['dia_semana']] ?> · <?= e(substr($w['hora_inicio'],0,5)) ?>–<?= e(substr($w['hora_fim'],0,5)) ?> · <?= $w['ativa']?'Ativo':'Inativo' ?></summary><form class="form-operacao" method="post" action="../processamento/profissional.php"><?php operationFields('intervalo'); ?><input type="hidden" name="id" value="<?= (int)$w['id'] ?>"><div class="grade-campos"><label>Dia<select name="dia"><?php foreach($days as $i=>$day): ?><option value="<?= $i ?>" <?= (int)$w['dia_semana']===$i?'selected':'' ?>><?= $day ?></option><?php endforeach; ?></select></label><label>Início<input type="time" name="inicio" required value="<?= e(substr($w['hora_inicio'],0,5)) ?>"></label><label>Fim<input type="time" name="fim" required value="<?= e(substr($w['hora_fim'],0,5)) ?>"></label></div><label><input type="checkbox" name="ativa" value="1" <?= $w['ativa']?'checked':'' ?>> Ativo</label><button class="botao botao-principal">Salvar intervalo</button></form><form method="post" action="../processamento/profissional.php"><?php operationFields('excluir_intervalo'); ?><input type="hidden" name="id" value="<?= (int)$w['id'] ?>"><button class="botao botao-secundario">Excluir intervalo</button></form></details><?php endforeach; if(!$d['disponibilidade']['weekly'])emptyState('Nenhuma disponibilidade semanal cadastrada.'); ?></div>
<details id="novo-intervalo" open><summary>Adicionar / corrigir intervalo</summary><form class="form-operacao" method="post" action="../processamento/profissional.php"><?php operationFields('intervalo'); ?><input type="hidden" name="id" value="<?= e(oldOperation('intervalo','id')) ?>"><div class="grade-campos"><label>Dia<select name="dia"><?php foreach($days as $i=>$day): ?><option value="<?= $i ?>" <?= (string)oldOperation('intervalo','dia',1)===(string)$i?'selected':'' ?>><?= $day ?></option><?php endforeach; ?></select></label><label>Início<input type="time" name="inicio" required value="<?= e(oldOperation('intervalo','inicio')) ?>"></label><label>Fim<input type="time" name="fim" required value="<?= e(oldOperation('intervalo','fim')) ?>"></label></div><label><input type="checkbox" name="ativa" value="1" <?= oldOperation('intervalo','ativa','1')==='1'?'checked':'' ?>> Disponibilizar este intervalo</label><button class="botao botao-principal">Salvar intervalo</button></form></details><div class="linha-divisoria"></div><h2>Horários concretos disponíveis</h2><form class="form-operacao" method="post" action="../processamento/profissional.php"><?php operationFields('gerar'); ?><label>Gerar / atualizar próximos dias<input name="dias" type="number" min="1" max="90" value="60" required></label><button class="botao botao-suave">Atualizar horários</button></form><details><summary><?= count($d['horarios']) ?> horários livres</summary><div class="horarios-reais"><?php foreach($d['horarios'] as $h): ?><span class="tag"><?= dateLabel($h['inicio_em']) ?> – <?= dateLabel($h['fim_em'],'H:i') ?></span><?php endforeach; if(!$d['horarios'])emptyState('Nenhum horário disponível cadastrado.'); ?></div></details></section>
