<details open><summary>Novo bloqueio / corrigir</summary><form class="form-operacao" method="post" action="../processamento/profissional.php"><?php operationFields('bloqueio'); ?><input type="hidden" name="id" value="<?= e(oldOperation('bloqueio','id')) ?>"><label>Início<input type="datetime-local" name="inicio" required value="<?= e(oldOperation('bloqueio','inicio')) ?>"></label><label>Fim<input type="datetime-local" name="fim" required value="<?= e(oldOperation('bloqueio','fim')) ?>"></label><label>Motivo (sem dados clínicos)<input name="motivo" maxlength="255" required value="<?= e(oldOperation('bloqueio','motivo')) ?>"></label><button class="botao botao-principal">Salvar bloqueio</button></form></details></article></aside></div>
